export function getMetinSkillTier(skillLevel = 1) {
  const lv = Number(skillLevel) || 1;
  if (lv >= 50) return 5; // L-Skill (Legendärer Meister _5)
  if (lv >= 40) return 4; // Perfekter Meister P (_4)
  if (lv >= 30) return 3; // Großmeister G (_3)
  if (lv >= 20) return 2; // Meister M (_2)
  return 1;               // Normal (_1)
}

export function getMetinPgFolder(classId = 'warrior', gender = 'm') {
  const cls = String(classId || 'warrior').toLowerCase();
  const g = String(gender || 'm').toLowerCase();
  const isFemale = (g === 'f' || g === 'female' || g === 'w');
  if (cls === 'warrior' || cls === 'sura') {
    return isFemale ? 'pc2' : 'pc';
  }
  return isFemale ? 'pc' : 'pc2';
}

const GLOBAL_SKILL_FALLBACK_CODES = {
  iron_body: 'cheongeun',
  horse_stomp: 'daejin',
  horse_charge: 'tanhwan',
  horse_wave: 'palbang',
  dragon_help: 'gicheon',
  dragon_blessing: 'hosin',
  natures_heal: 'jeongeop',
};

export function resolveMetinSkill(classId, skillId, doctrine = '', skillLevel = 1, gender = 'm') {
  const cls = String(classId || 'warrior').toLowerCase();
  const clsCfg = METIN_SKILL_CATALOG.classes[cls] || METIN_SKILL_CATALOG.classes.warrior;
  if (!clsCfg) return null;
  const doc = String(doctrine || '').toLowerCase();
  const skMap = clsCfg.skills[skillId];
  let code = skMap ? ((doc && skMap[doc]) ? skMap[doc] : skMap.default) : GLOBAL_SKILL_FALLBACK_CODES[skillId];
  if (!code && METIN_SKILL_CATALOG.skillsByCode[skillId]) code = skillId;
  if (!code) {
    for (const cObj of Object.values(METIN_SKILL_CATALOG.classes)) {
      if (cObj.skills?.[skillId]) {
        code = cObj.skills[skillId].default;
        break;
      }
    }
  }
  const entry = code ? METIN_SKILL_CATALOG.skillsByCode[code] : null;
  if (!entry) return null;
  const tier = getMetinSkillTier(skillLevel);
  const tierData = entry.tiers[String(tier)] || entry.tiers['4'] || entry.tiers['1'];
  const pcFolder = getMetinPgFolder(cls, gender);
  let effTierData = tierData;
  if (tier === 5 && entry.tiers['4'] && entry.tiers['1']) {
    const t5Evs = (tierData?.[pcFolder]?.events || tierData?.pc?.events || []).map(e => e.effectKey).join('|');
    const t1Evs = (entry.tiers['1']?.[pcFolder]?.events || entry.tiers['1']?.pc?.events || []).map(e => e.effectKey).join('|');
    const t4Evs = (entry.tiers['4']?.[pcFolder]?.events || entry.tiers['4']?.pc?.events || []).map(e => e.effectKey).join('|');
    if (t4Evs && t5Evs === t1Evs && t4Evs !== t1Evs) {
      effTierData = entry.tiers['4'];
    }
  }
  const rawMsa = (effTierData && effTierData[pcFolder]) || (effTierData && effTierData.pc) || null;
  const msa = rawMsa ? {
    ...rawMsa,
    events: (rawMsa.events || []).map(ev => ({
      ...ev,
      effect: METIN_SKILL_CATALOG.effects[ev.effectKey] || null
    })).filter(ev => ev.effect)
  } : null;
  const rawLoop = (effTierData && effTierData.loop) || (tierData && tierData.loop) || null;
  const loop = (rawLoop && METIN_SKILL_CATALOG.effects[rawLoop.effectKey]) ? {
    bone: rawLoop.bone,
    effectKey: rawLoop.effectKey,
    effect: METIN_SKILL_CATALOG.effects[rawLoop.effectKey]
  } : null;
  const soundUrl = (entry.sound && entry.sound[pcFolder]) || (entry.sound && entry.sound.pc) || null;
  return {
    code,
    classId: cls,
    skillId,
    doctrine: doc || clsCfg.doctrines[0],
    tier,
    isLSkill: tier === 5,
    pcFolder,
    name: (tierData && tierData.name) || entry.names[String(tier)] || entry.names['1'] || skillId,
    names: entry.names,
    desc: entry.desc,
    soundUrl,
    msa,
    loop
  };
}
